begin
 if not exists(select 1 from public.organization_members where organization_id='93228bbb-6397-41e3-b8be-21ee7060eda7' and user_id=p_user and role in('owner','admin','manager')) then raise exception 'FORBIDDEN';end if;
 with history as materialized(select * from public.luna_negative_v2_history()),unused as(
 select r.id review_id,r.organization_id,r.establishment_id,e.name establishment_name,r.rating,r.original_text,r.original_language,
 (select jsonb_agg(jsonb_build_object('id',t.id,'language',t.language,'translated_text',t.translated_text,'created_at',t.created_at,'updated_at',t.updated_at) order by t.id) from public.review_translations t where t.review_id=r.id and t.language='en') review_translations
 from public.reviews r join public.establishments e on e.id=r.establishment_id
 where r.organization_id='93228bbb-6397-41e3-b8be-21ee7060eda7' and e.organization_id=r.organization_id and length(trim(coalesce(r.original_text,'')))>0 and not exists(select 1 from history h where h.review_id=r.id)
 ) select jsonb_build_object('history_tables','["analysis_corrected_reference_labels","analysis_corrected_references","analysis_decisions_configurations","analysis_decisions_evidence40_events","analysis_decisions_evidence40_plans","analysis_decisions_evidence40_runs","analysis_decisions_evidence40_tasks","analysis_decisions_experiments","analysis_decisions_results","analysis_decisions_tasks","analysis_gold_adjudication_events","analysis_gold_adjudication_items","analysis_gold_adjudication_labels","analysis_gold_adjudications","analysis_gold_events","analysis_gold_labels","analysis_gold_set_reviews","analysis_gold_sets","analysis_jev_compact_ai_references","analysis_jev_compact_authorizations","analysis_jev_compact_events","analysis_jev_compact_items","analysis_jev_compact_results","analysis_jev_compact_runs","analysis_jev_compact_seals","analysis_jev_compact_sets","analysis_jev_compact_tasks","analysis_jev_compact_texts","analysis_jev_economy_comparisons","analysis_jev_economy_configurations","analysis_jev_experimental_configurations","analysis_jev_exploratory_approvals","analysis_jev_exploratory_corrections","analysis_jev_exploratory_events","analysis_jev_exploratory_items","analysis_jev_exploratory_review_uses","analysis_jev_exploratory_runs","analysis_jev_exploratory_tasks","analysis_jev_hybrid_authorizations","analysis_jev_hybrid_controls","analysis_jev_hybrid_events","analysis_jev_hybrid_jobs","analysis_jev_hybrid_plans","analysis_jev_hybrid_verdicts","analysis_jev_independent_ai_error_audits","analysis_jev_independent_configurations","analysis_jev_independent_results","analysis_jev_independent_runs","analysis_jev_independent_tasks","analysis_jev_pilot_authorizations","analysis_jev_pilot_events","analysis_jev_pilot_evidence_audits","analysis_jev_pilot_evidence_v21","analysis_jev_pilot_evidence_v3","analysis_jev_pilot_evidence_v3_controls","analysis_jev_pilot_evidence_v3_reserved_evaluations","analysis_jev_pilot_jobs","analysis_jev_pilot_snapshots","analysis_jev_pilot_tasks","analysis_jev_review_cache","analysis_jev_review_cache_events","analysis_jev_v12_ai_miss_audits","analysis_jev_v12_results","analysis_jev_v12_runs","analysis_jev_v12_tasks","analysis_jev_v13_configurations","analysis_jev_v13_fresh_ai_reference_notes","analysis_jev_v13_fresh_posthoc_ai_audits","analysis_jev_v13_results","analysis_jev_v13_runs","analysis_jev_v13_sealed_inputs","analysis_jev_v13_tasks","analysis_luna_balanced_cases","analysis_luna_balanced_reference_seals","analysis_luna_balanced_references","analysis_luna_balanced_sets","analysis_luna_multirest_cases","analysis_luna_multirest_events","analysis_luna_multirest_plans","analysis_luna_multirest_reference_seals","analysis_luna_multirest_references","analysis_luna_multirest_results","analysis_luna_multirest_runs","analysis_luna_multirest_sets","analysis_luna_multirest_tasks","analysis_luna_native48_events","analysis_luna_native48_plans","analysis_luna_native48_results","analysis_luna_native48_runs","analysis_luna_native48_tasks","analysis_negative_ai_exploratory_results","analysis_negative_ai_exploratory_runs","analysis_negative_ai_exploratory_tasks","analysis_negative_ai_review_rechecks","analysis_negative_ai_theme_rechecks","analysis_negative_validation_ai_preannotations","analysis_negative_validation_events","analysis_negative_validation_labels","analysis_negative_validation_results","analysis_negative_validation_reviews","analysis_negative_validation_runs","analysis_negative_validation_tasks","analysis_representative_human_events","analysis_representative_human_labels","analysis_representative_human_test_items","analysis_representative_human_tests","analysis_review_english_translation_overrides","analysis_v11_independent_holdout_ai_references","analysis_v11_independent_holdout_ai_seals","analysis_v11_independent_holdout_items","analysis_v11_independent_holdout_sets","analysis_v9_finding_audit_events","analysis_v9_finding_audit_items","analysis_v9_finding_audit_labels","analysis_v9_finding_audits","historical_establishment_reports","historical_jev_analysis_tasks","historical_jev_run_metrics","historical_jev_v10_run_metrics","historical_jev_v11_run_metrics","historical_report_runs","jev_benchmark_runs"]'::jsonb,'historical_review_ids',(select count(*) from history),'total_text_reviews',(select count(*) from public.reviews where organization_id='93228bbb-6397-41e3-b8be-21ee7060eda7' and length(trim(coalesce(original_text,'')))>0),'unused',coalesce((select jsonb_agg(to_jsonb(u) order by u.review_id) from unused u),'[]'::jsonb)) into result;
 return result;
end $fn$;
revoke all on function public.luna_negative_v2_inventory(uuid) from public,anon,authenticated;
grant execute on function public.luna_negative_v2_inventory(uuid) to service_role;
create table public.analysis_luna_negative_v2_sets(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),
 version text not null check(version='luna-negative-focused-v2'),body jsonb not null,body_sha256 text not null check(body_sha256~'^[a-f0-9]{64}$'),
 config_sha256 text not null,selector_sha256 text not null,review_count int not null check(review_count between 1 and 32),question_count int not null check(question_count between 1 and 40),
 created_by uuid not null references auth.users(id),sealed_at timestamptz not null default now(),paid_enabled boolean not null default false check(not paid_enabled),production_enabled boolean not null default false check(not production_enabled),
 unique(organization_id,version),unique(id,organization_id)
);
create table public.analysis_luna_negative_v2_reviews(
 set_id uuid not null,organization_id uuid not null,review_id uuid not null references public.reviews(id),establishment_id uuid not null references public.establishments(id),position int not null check(position between 1 and 32),original_text_sha256 text not null,analysis_text_sha256 text not null,review_sha256 text not null,body jsonb not null,
 primary key(set_id,review_id),unique(set_id,position),foreign key(set_id,organization_id) references public.analysis_luna_negative_v2_sets(id,organization_id)
);
create table public.analysis_luna_negative_v2_associations(
 set_id uuid not null,organization_id uuid not null,review_id uuid not null,association_id text not null,theme_key text not null,polarity text not null check(polarity in('positive','negative')),body jsonb not null,
 primary key(set_id,review_id,theme_key),unique(set_id,association_id),foreign key(set_id,review_id) references public.analysis_luna_negative_v2_reviews(set_id,review_id),foreign key(set_id,organization_id) references public.analysis_luna_negative_v2_sets(id,organization_id)
);
create table public.analysis_luna_negative_v2_reference_seals(
 id uuid primary key default gen_random_uuid(),set_id uuid not null unique,organization_id uuid not null,dataset_sha256 text not null,reference_sha256 text not null,body jsonb not null,annotation_model text not null check(annotation_model='GPT-6'),reference_type text not null check(reference_type='GPT6_AI_reference_not_independent_human_Gold'),created_by uuid not null references auth.users(id),sealed_at timestamptz not null default now(),
 foreign key(set_id,organization_id) references public.analysis_luna_negative_v2_sets(id,organization_id),unique(id,set_id,organization_id)
);
create table public.analysis_luna_negative_v2_references(
 set_id uuid not null,organization_id uuid not null,seal_id uuid not null,review_id uuid not null,theme_key text not null,analysis_text_sha256 text not null,choice text not null check(choice in('absent','positive','negative','both','uncertain')),justification text not null check(length(trim(justification))>0),
 primary key(set_id,review_id,theme_key),foreign key(set_id,review_id,theme_key) references public.analysis_luna_negative_v2_associations(set_id,review_id,theme_key),foreign key(seal_id,set_id,organization_id) references public.analysis_luna_negative_v2_reference_seals(id,set_id,organization_id)
);
do $$declare t text;begin foreach t in array array['analysis_luna_negative_v2_sets','analysis_luna_negative_v2_reviews','analysis_luna_negative_v2_associations','analysis_luna_negative_v2_reference_seals','analysis_luna_negative_v2_references'] loop
 execute format('alter table public.%I enable row level security',t);
 execute format('revoke all on public.%I from anon,authenticated',t);
 execute format('grant select on public.%I to authenticated',t);
 execute format('grant all on public.%I to service_role',t);
 execute format('create policy luna_negative_org_read on public.%I for select to authenticated using(exists(select 1 from public.organization_members m where m.organization_id=%I.organization_id and m.user_id=(select auth.uid()) and m.role in(''owner'',''admin'',''manager'')))',t,t);
 execute format('create trigger luna_negative_immutable before update or delete on public.%I for each row execute function public.pilot_evidence_immutable()',t);
 execute format('create index %I on public.%I(organization_id)',t||'_org',t);
end loop;end $$;
create index luna_negative_review_review on public.analysis_luna_negative_v2_reviews(review_id);
create index luna_negative_review_est on public.analysis_luna_negative_v2_reviews(establishment_id);
create index luna_negative_set_actor on public.analysis_luna_negative_v2_sets(created_by);
create index luna_negative_seal_actor on public.analysis_luna_negative_v2_reference_seals(created_by);
create index luna_negative_ref_seal on public.analysis_luna_negative_v2_references(seal_id,set_id,organization_id);
create function public.save_luna_negative_v2_set(p_user uuid,p_body jsonb,p_sha text) returns uuid language plpgsql security invoker set search_path='' as $fn$
declare sid uuid;item jsonb;a jsonb;provider text;
begin
 if not exists(select 1 from public.organization_members where organization_id='93228bbb-6397-41e3-b8be-21ee7060eda7' and user_id=p_user and role in('owner','admin','manager')) then raise exception 'FORBIDDEN';end if;
 perform pg_advisory_xact_lock(hashtextextended('luna-negative-focused-v2:93228bbb-6397-41e3-b8be-21ee7060eda7',0));
 select id into sid from public.analysis_luna_negative_v2_sets where organization_id='93228bbb-6397-41e3-b8be-21ee7060eda7' and version='luna-negative-focused-v2';
 if found then if not exists(select 1 from public.analysis_luna_negative_v2_sets where id=sid and body_sha256=p_sha) then raise exception 'NEGATIVE_V2_SET_IMMUTABLE';end if;return sid;end if;
 if p_body->>'version' is distinct from 'luna-negative-focused-v2' or p_body->>'organization_id' is distinct from '93228bbb-6397-41e3-b8be-21ee7060eda7' or p_body->>'paid_enabled' is distinct from 'false' or p_body->>'production_enabled' is distinct from 'false' or p_body->>'new_paid_calls' is distinct from '0' or p_body->>'reference_count' is distinct from '0' or p_body->'config'->>'model' is distinct from 'gpt-6-luna' or p_body->'config'->>'paid_enabled' is distinct from 'false' or p_body->'config'->>'automatic_retry' is distinct from 'false' or p_body->>'future_calls' is distinct from p_body->>'review_count' or p_sha is distinct from encode(extensions.digest(public.jev_economy_canonical(p_body),'sha256'),'hex') or p_body->>'config_sha256' is distinct from encode(extensions.digest(public.jev_economy_canonical(p_body->'config'),'sha256'),'hex') or p_body->>'reviews_sha256' is distinct from encode(extensions.digest(public.jev_economy_canonical(p_body->'reviews'),'sha256'),'hex') or jsonb_array_length(p_body->'reviews') not between 1 and 32 or jsonb_array_length(p_body->'reviews')<>(p_body->>'review_count')::int or (select count(distinct it->>'review_id') from jsonb_array_elements(p_body->'reviews')it)<>jsonb_array_length(p_body->'reviews') or (select sum(jsonb_array_length(it->'associations')) from jsonb_array_elements(p_body->'reviews')it)<>(p_body->>'question_count')::int or (p_body->>'question_count')::int>40 then raise exception 'NEGATIVE_V2_SET_INVALID';end if;
 if exists(select 1 from public.luna_negative_v2_history() h join jsonb_array_elements(p_body->'reviews') it on it->>'review_id'=h.review_id::text) then raise exception 'NEGATIVE_V2_HISTORICAL_OVERLAP';end if;
 for item in select value from jsonb_array_elements(p_body->'reviews') loop
  if not exists(select 1 from public.reviews r join public.establishments e on e.id=r.establishment_id where r.id=(item->>'review_id')::uuid and r.organization_id='93228bbb-6397-41e3-b8be-21ee7060eda7' and e.organization_id=r.organization_id and r.establishment_id=(item->>'establishment_id')::uuid and r.original_text=item->>'original_text' and r.rating=(item->>'overall_rating')::int) or length(trim(item->>'analysis_text'))=0 or item->>'original_text_sha256' is distinct from encode(extensions.digest(item->>'original_text','sha256'),'hex') or item->>'analysis_text_sha256' is distinct from encode(extensions.digest(item->>'analysis_text','sha256'),'hex') or item->>'review_sha256' is distinct from encode(extensions.digest(public.jev_economy_canonical(item-'review_sha256'),'sha256'),'hex') or jsonb_array_length(item->'associations') not between 1 and 2 or (select count(distinct q->>'theme_key') from jsonb_array_elements(item->'associations')q)<>jsonb_array_length(item->'associations') or jsonb_array_length(item->'payload'->'questions')<>jsonb_array_length(item->'associations') or item->'payload'->>'model' is distinct from 'gpt-6-luna' or item->>'request_sha256' is distinct from encode(extensions.digest(public.jev_economy_canonical(item->'payload'),'sha256'),'hex') or (item->'payload'->>'input')::jsonb->>'analysis_text' is distinct from item->>'analysis_text' or (item->'payload'->>'input')::jsonb ?| array['rating','original_text','reference','human_choice'] then raise exception 'NEGATIVE_V2_REVIEW_CHANGED';end if;
  if item->>'analysis_source'='original_en' then
   if not exists(select 1 from public.reviews where id=(item->>'review_id')::uuid and original_language='en' and original_text=item->>'analysis_text') then raise exception 'NEGATIVE_V2_EN_CHANGED';end if;
  elsif item->>'analysis_source'='google_translation_en' then
   if not exists(select 1 from public.review_translations where id=(item->'translation_provenance'->>'id')::uuid and review_id=(item->>'review_id')::uuid and language='en' and translated_text=item->>'analysis_text') then raise exception 'NEGATIVE_V2_EN_CHANGED';end if;
  else raise exception 'NEGATIVE_V2_EN_SOURCE_INVALID';end if;
 end loop;
 insert into public.analysis_luna_negative_v2_sets(organization_id,version,body,body_sha256,config_sha256,selector_sha256,review_count,question_count,created_by) values('93228bbb-6397-41e3-b8be-21ee7060eda7','luna-negative-focused-v2',p_body,p_sha,p_body->>'config_sha256',p_body->>'selector_sha256',(p_body->>'review_count')::int,(p_body->>'question_count')::int,p_user) returning id into sid;
 for item in select value from jsonb_array_elements(p_body->'reviews') loop
  insert into public.analysis_luna_negative_v2_reviews(set_id,organization_id,review_id,establishment_id,position,original_text_sha256,analysis_text_sha256,review_sha256,body) values(sid,'93228bbb-6397-41e3-b8be-21ee7060eda7',(item->>'review_id')::uuid,(item->>'establishment_id')::uuid,(item->>'position')::int,item->>'original_text_sha256',item->>'analysis_text_sha256',item->>'review_sha256',item);
  for a in select value from jsonb_array_elements(item->'associations')loop
   if a->>'theme_key' not in('food_quality','freshness','cooking','temperature','portions','presentation','drinks','variety','consistency','friendly_staff','attentiveness','wait_time','coordination','communication','order_accuracy','professionalism','atmosphere','decor','noise','comfort','cleanliness','location','value','billing','price_level') then raise exception 'NEGATIVE_V2_THEME_INVALID';end if;
   insert into public.analysis_luna_negative_v2_associations(set_id,organization_id,review_id,association_id,theme_key,polarity,body) values(sid,'93228bbb-6397-41e3-b8be-21ee7060eda7',(item->>'review_id')::uuid,a->>'association_id',a->>'theme_key',a->>'polarity',a);
  end loop;
 end loop;return sid;
end $fn$;
create function public.seal_luna_negative_v2_references(p_user uuid,p_set uuid,p_body jsonb,p_sha text) returns uuid language plpgsql security invoker set search_path='' as $fn$
declare s public.analysis_luna_negative_v2_sets;sid uuid;item jsonb;
begin
 select * into s from public.analysis_luna_negative_v2_sets where id=p_set;
 if s.id is null or not exists(select 1 from public.organization_members where organization_id=s.organization_id and user_id=p_user and role in('owner','admin','manager')) then raise exception 'FORBIDDEN';end if;
 if p_body->>'dataset_sha256' is distinct from s.body_sha256 or p_body->>'annotation_model' is distinct from 'GPT-6' or p_body->>'reference_type' is distinct from 'GPT6_AI_reference_not_independent_human_Gold' or jsonb_array_length(p_body->'items')<>s.question_count or (select count(distinct (q->>'review_id')||':'||(q->>'theme_key')) from jsonb_array_elements(p_body->'items')q)<>s.question_count or p_sha is distinct from encode(extensions.digest(public.jev_economy_canonical(p_body),'sha256'),'hex') then raise exception 'NEGATIVE_V2_REFERENCE_INVALID';end if;
 for item in select value from jsonb_array_elements(p_body->'items') loop
  if item->>'choice' is null or item->>'choice' not in('absent','positive','negative','both','uncertain') or coalesce(length(trim(item->>'justification')),0)=0 or not exists(select 1 from public.analysis_luna_negative_v2_associations a join public.analysis_luna_negative_v2_reviews r using(set_id,review_id) where a.set_id=s.id and a.review_id=(item->>'review_id')::uuid and a.theme_key=item->>'theme_key' and r.analysis_text_sha256=item->>'analysis_text_sha256') then raise exception 'NEGATIVE_V2_REFERENCE_ITEM_CHANGED';end if;
 end loop;
 perform pg_advisory_xact_lock(hashtextextended(p_set::text||':negative-v2-references',0));
 select id into sid from public.analysis_luna_negative_v2_reference_seals where set_id=p_set;
 if found then if not exists(select 1 from public.analysis_luna_negative_v2_reference_seals where id=sid and reference_sha256=p_sha) then raise exception 'NEGATIVE_V2_REFERENCE_IMMUTABLE';end if;return sid;end if;
 insert into public.analysis_luna_negative_v2_reference_seals(set_id,organization_id,dataset_sha256,reference_sha256,body,annotation_model,reference_type,created_by) values(s.id,s.organization_id,s.body_sha256,p_sha,p_body,'GPT-6','GPT6_AI_reference_not_independent_human_Gold',p_user) returning id into sid;
 for item in select value from jsonb_array_elements(p_body->'items')loop
 insert into public.analysis_luna_negative_v2_references(set_id,organization_id,seal_id,review_id,theme_key,analysis_text_sha256,choice,justification) values(s.id,s.organization_id,sid,(item->>'review_id')::uuid,item->>'theme_key',item->>'analysis_text_sha256',item->>'choice',item->>'justification');end loop;return sid;
end $fn$;
revoke all on function public.save_luna_negative_v2_set(uuid,jsonb,text),public.seal_luna_negative_v2_references(uuid,uuid,jsonb,text) from public,anon,authenticated;
grant execute on function public.save_luna_negative_v2_set(uuid,jsonb,text),public.seal_luna_negative_v2_references(uuid,uuid,jsonb,text) to service_role;
